import os
os.environ['MPLCONFIGDIR']='/tmp/monza-matplotlib'
import json,csv,pathlib,math
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D
root=pathlib.Path(__file__).resolve().parent
metrics=json.loads((root/'controlled_metrics.json').read_text());real=json.loads((root/'real_marker_metrics.json').read_text())
rows=list(csv.DictReader(open(root/'controlled_predictions.csv')))
names={'LK_RANSAC':'KLT + RANSAC','Dense_flow':'Flusso integrato','Rotated_NCC':'Template a rotazioni note (NCC)','Fusion_NCC_flow':'Template + flusso + filtro'}
colors={'LK_RANSAC':'#9261bc','Dense_flow':'#df7b2a','Rotated_NCC':'#1865dc','Fusion_NCC_flow':'#148578'}
scenario_names={'clear':'Immagine leggibile','blur_light':'Sfocatura e luce variabile','occlusion_25':'Copertura inferiore: fino al 25% dell’altezza','occlusion_50':'Copertura inferiore: fino al 50% dell’altezza'}
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':11})
fig,axs=plt.subplots(2,2,figsize=(16,11),dpi=130,sharex=True,sharey=True)
fig.patch.set_facecolor('#f3f6fa');fig.subplots_adjust(left=.075,right=.97,top=.79,bottom=.17,hspace=.25,wspace=.13)
for ax,(scenario,title) in zip(axs.flat,scenario_names.items()):
 selected=[r for r in rows if r['scenario']==scenario];reference=[r for r in selected if r['method']=='Dense_flow'];t=np.array([float(r['time_s']) for r in reference]);truth=np.array([float(r['reference_apparent_deg']) for r in reference])
 for method in names:
  a=[r for r in selected if r['method']==method];values=np.array([float(r['estimate_apparent_deg']) if r['estimate_apparent_deg'] else np.nan for r in a]);ax.plot(t,values,color=colors[method],lw=1.7 if method=='Fusion_NCC_flow' else 1.2,alpha=.85)
 ax.plot(t,truth,color='#182b47',lw=1.4,ls='--');ax.axhline(0,color='#93a3b8',lw=.8);ax.set_facecolor('white');ax.grid(color='#e1e8f1');ax.set_title(title,loc='left',color='#203650',fontsize=12,weight='bold');ax.set_ylim(-105,105);ax.set_xlim(0,12)
 for spine in ax.spines.values():spine.set_visible(False)
for ax in axs[1]:ax.set_xlabel('Tempo simulato (s)')
for ax in axs[:,0]:ax.set_ylabel('Rotazione 2D apparente (°)')
fig.text(.05,.96,'DRIVING NOTES / CONFRONTO DEI METODI',fontsize=10,color='#73849b',weight='bold')
fig.text(.05,.92,'Angoli con segno: precisione e continuità',fontsize=25,color='#172d4a',weight='bold')
fig.text(.05,.883,'PROVA CONTROLLATA · rotazioni artificiali di una texture estratta dal video · non sono i giri a Monza',fontsize=12,color='#8c5921',weight='bold')
handles=[Line2D([0],[0],color='#182b47',ls='--',lw=1.4,label='Angolo noto')]+[Line2D([0],[0],color=colors[k],lw=2,label=v) for k,v in names.items()]
fig.legend(handles=handles,loc='upper left',bbox_to_anchor=(.045,.862),ncol=3,frameon=False,fontsize=10)
fig.text(.05,.094,'La linea può essere continua e sbagliata: il flusso integrato accumula deriva durante le occlusioni.',fontsize=12,color='#334e6c',weight='bold')
fig.text(.05,.062,'I vuoti sono stime rifiutate. I risultati in gradi misurano solo questa rotazione 2D nota, non la precisione sullo sterzo reale.',fontsize=10,color='#657a93')
fig.savefig(root/'confronto-metodi.png',facecolor=fig.get_facecolor())
# Generate the tables from measured results, keeping coverage next to conditional errors.
lines=['# Sterzo con segno: confronto dei metodi','', '**Convenzione richiesta per un futuro canale reale: destra positiva, sinistra negativa. L’indice 0–100 di attività già pubblicato non è uno sterzo e non va trasformato in gradi aggiungendogli semplicemente un segno.**','', '## Risultato pratico','', 'Il riconoscimento diretto del riferimento evita la deriva del flusso integrato. Nei test controllati il template NCC è il più preciso con occlusione moderata; la fusione template/flusso restituisce più campioni, ma può aumentare l’errore mentre predice attraverso un tratto coperto. Sul piccolo campione reale, colore del pulsante e controllo del bordo scuro sono i candidati più promettenti; il solo template produce falsi agganci quando il pulsante scompare.','', '**Non è ancora possibile dichiarare quale metodo misuri meglio i gradi meccanici sui due giri:** manca una telemetria sterzo di riferimento e il volante è spesso coperto. I due confronti sotto misurano quantità diverse e non vanno confusi.','', '![Confronto delle rotazioni note](confronto-metodi.png)','', '## 1. Prova con angoli noti — gradi apparenti 2D','', 'Sono usati 145 istanti per scenario, quattro scenari e quattro metodi: 580 immagini di prova, 2.320 stime richieste. Una texture reale della zona volante viene ruotata artificialmente fra −75° e +65°. Sono aggiunti movimento comune della camera, sfocatura, variazioni di luce e occlusioni. Tutti i metodi ricevono le stesse immagini e la stessa stabilizzazione della scocca. Segno positivo: rotazione oraria della texture nell’immagine simulata. Questo **non calibra automaticamente destra/sinistra del volante reale**.','', 'Le percentuali dei due scenari di copertura indicano l’altezza massima della fascia inferiore coprente rispetto al diametro del disco simulato, non la percentuale esatta di area occultata; la fascia varia nel tempo. Gli scenari sono 2D: non riproducono completamente la prospettiva, la deformazione dei guanti e le occlusioni dei filmati. Le soglie sono fisse per i quattro scenari. Gli errori sono calcolati soltanto quando il metodo restituisce un valore; la copertura e gli errori di segno sono riportati accanto. Un metodo che non restituisce valori durante la sterzata non è preciso solo perché riconosce i fotogrammi iniziali a zero.','', '| Scenario | Metodo | Errore medio ° | P95 ° | Copertura | Segni errati / pose attive restituite |','|---|---|---:|---:|---:|---:|']
for m in metrics:
 err=f"{m['mae_deg']:.2f}" if m['active_returned']>=10 else 'non rappresentativo'
 p95=f"{m['p95_deg']:.2f}" if m['active_returned']>=10 else '—'
 lines.append(f"| {scenario_names[m['scenario']]} | {names[m['method']]} | {err} | {p95} | {m['coverage_pct']:.1f}% | {m['sign_errors']}/{m['active_returned']} |")
lines += ['', 'Il flusso integrato rimane continuo anche quando deriva: con occlusione moderata l’errore medio è circa 14,5°, con occlusione estesa circa 36,7°. Rendere più liscia la curva non corregge questo errore. Con occlusione estesa anche il template restituisce solo il 20% dei campioni: il basso errore dei pochi campioni visibili non dimostra copertura del giro.', '', '## 2. Prova sui fotogrammi reali — pixel, non gradi','', 'È stato scelto un riferimento realmente solidale al volante: il pulsante azzurro, distinguendolo dal casco e dal logo sul guanto. Il campione riguarda un breve tratto della prima chicane: 14 fotogrammi dai due video, uno usato come calibrazione condivisa e escluso dai punteggi; restano **5 fotogrammi con riferimento visibile e 8 con riferimento non visibile nel ritaglio**. È un test preliminare selezionato per visibilità/occlusione, non un campione casuale rappresentativo di tutto il giro.', '', 'Il ritaglio analizzato è di 360×170 pixel (coordinate originali x=1100…1460, y=1020…1190). «Non visibile» include sia copertura sia uscita dal ritaglio: non è una misura della visibilità del volante nell’intero video. Le coordinate sono letture visive approssimative dei ritagli, con incertezza di circa ±3 pixel e fino a ±5 nei campioni scuri. Gli scarti inferiori a questa incertezza non permettono di distinguere statisticamente due metodi. Il KLT qui è un riaggancio diretto al riferimento condiviso; non è il benchmark sequenziale KLT/RANSAC della prova controllata.', '', '| Metodo | Scarto mediano dalle annotazioni (px) | Visibili restituiti | Falsi agganci quando non visibile |','|---|---:|---:|---:|']
rnames={'Color_circle':'Colore + circolarità + bordo scuro','Color_NCC_consensus':'Accordo colore + template','NCC_marker':'Solo template del pulsante','LK_direct_reference':'KLT diretto dal riferimento','SIFT_affine':'SIFT + trasformazione affine'}
for m in real:
 err=f"≈{m['median_error_px']:.1f}" if m['median_error_px'] is not None else 'non valutabile'
 lines.append(f"| {rnames[m['method']]} | {err} | {m['returned_visible']}/{m['visible_samples']} | {m['false_detections_when_occluded']}/{m['occluded_samples']} |")
lines += ['', 'Nel campione, colore e accordo colore/template sono sostanzialmente equivalenti entro l’incertezza delle annotazioni. Il solo template riconosce bene il punto quando visibile, ma accetta sei falsi agganci su otto casi non visibili: non è affidabile da solo. KLT e SIFT non restituiscono stime accettate sulle pose di valutazione: non se ne può calcolare un errore affidabile.', '', 'Una prova aggiuntiva, riproducibile con `real_marker_methods.py --jpeg-quality 98`, di ricompressione JPEG a qualità 98 fa perdere un campione visibile ai due metodi che usano il colore (4/5 invece di 5/5). Questo segnala sensibilità alle soglie e conferma che serve una verifica più ampia prima di parlare di robustezza.', '', '[Ritagli e confronto del punto annotato](real_marker_review.jpg) · [Annotazioni](real_marker_annotations.json) · [Risultati reali](real_marker_predictions.csv) · [Risultati controllati](controlled_predictions.csv)', '', '## Come rendere più precisa la prossima versione','', '1. **Seguire riferimenti rigidi del volante**, per esempio due pulsanti riconoscibili; usare la scocca solo per la camera e lo zero. Le mani possono muoversi sul volante e generare un segno errato.', '2. **Ritrovare il riferimento a ogni fotogramma e seguire una zona di ricerca mobile**, verificando insieme colore, forma e geometria. Il flusso ottico deve collegare gli agganci, non determinare da solo l’angolo per tutto il giro.', '3. **Calibrare la prospettiva e il segno.** Una linea della scocca non basta a convertire qualsiasi movimento 2D in gradi meccanici: servono un asse/centro e una geometria coerente del volante. Il verso va verificato su una manovra nota.', '4. **Filtrare dopo aver rifiutato i falsi agganci.** Un filtro temporale può ridurre rumore e salti, ma deve dichiarare quando sta predicendo. Nei test la fusione copre più fotogrammi, non è sempre la più accurata.', '5. **Limitare i tratti ricostruiti.** Da testare come limite prudente circa 0,15–0,2 s per colmare un buco corto; non è una prestazione già verificata qui. Quando il riferimento rimane nascosto, lasciare un buco invece di inventare una curva continua.', '', 'Queste prove non sostituiscono una misura reale dello sterzo. Non è stata caricata una nuova curva in gradi sui due giri come se fosse validata.', '', '## Riproduzione','', 'Con Python, NumPy, OpenCV e Matplotlib, dalla radice del repository:', '', '```bash','OPENBLAS_NUM_THREADS=1 python telemetry/monza/steering/benchmark/controlled_methods.py','python telemetry/monza/steering/benchmark/real_marker_methods.py','python telemetry/monza/steering/benchmark/real_marker_methods.py --jpeg-quality 98','python telemetry/monza/steering/benchmark/make_report.py','```', '', 'Gli input sono inclusi: texture di riferimento e ritagli dei fotogrammi. Le annotazioni sono visive e il fotogramma di calibrazione non è valutato. Gli script producono CSV e JSON con i risultati; non modificano i dati di telemetria dei due giri.']
(root/'README.md').write_text('\n'.join(lines)+'\n')
print('Report and signed controlled-angle comparison saved.')
